// Modern HD 2D Chibi спрайт-банк врагов, пропсов и гладких HD-тайлов NOCTIS
export interface WorldSpriteBank {
  ready: boolean;
  enemies: Record<string, HTMLImageElement>;
  props: Record<string, HTMLImageElement>;
  tiles: { floor: HTMLImageElement; wall: HTMLImageElement };
  onTilesReady: (cb: () => void) => void;
}

const ENEMY_DATA: Record<string, string> = {"bat": "data:image/webp;base64,", "goblin": "data:image/webp;base64,", "goblinArcher": "data:image/webp;base64,", "spider": "data:image/webp;base64,", "webSpider": "data:image/webp;base64,", "skeleton": "data:image/webp;base64,", "skelArcher": "data:image/webp;base64,", "necro": "data:image/webp;base64,", "orc": "data:image/webp;base64,", "shaman": "data:image/webp;base64,", "ogre": "data:image/webp;base64,", "wraith": "data:image/webp;base64,", "mimic": "data:image/webp;base64,", "boss": "data:image/webp;base64,"};
const PROP_DATA: Record<string, string> = {"merchant": "data:image/webp;base64,", "shrine": "data:image/webp;base64,", "barrel": "data:image/webp;base64,", "crate": "data:image/webp;base64,", "chest_closed": "data:image/webp;base64,", "chest_open": "data:image/webp;base64,", "rat": "data:image/webp;base64,", "ironchest_closed": "data:image/webp;base64,", "ironchest_open": "data:image/webp;base64,", "vault_closed": "data:image/webp;base64,", "vault_open": "data:image/webp;base64,", "pickup_potion": "data:image/webp;base64,", "pickup_key": "data:image/webp;base64,", "pickup_gold": "data:image/webp;base64,", "pickup_xp": "data:image/webp;base64,", "map_bg": "data:image/jpeg;base64,", "map_hero": "data:image/webp;base64,", "map_merchant": "data:image/webp;base64,", "map_boss": "data:image/webp;base64,", "map_seal": "data:image/webp;base64,", "brazier": "data:image/webp;base64,"};
const TILE_DATA = {"floor": "data:image/jpeg;base64,", "wall": "data:image/jpeg;base64,"};

let bank: WorldSpriteBank | null = null;
const tileCallbacks: (() => void)[] = [];
let tilesLoadedCount = 0;

export function getWorldSprites(): WorldSpriteBank {
  if (bank) return bank;
  const total = Object.keys(ENEMY_DATA).length + Object.keys(PROP_DATA).length + 2;
  let loaded = 0;
  const mk = (src: string, isTile = false): HTMLImageElement => {
    const img = new Image();
    img.onload = () => {
      loaded++;
      if (loaded >= total && bank) bank.ready = true;
      if (isTile) {
        tilesLoadedCount++;
        if (tilesLoadedCount >= 2) while (tileCallbacks.length) tileCallbacks.shift()?.();
      }
    };
    img.src = src;
    return img;
  };
  const enemyImgs: Record<string, HTMLImageElement> = {};
  for (const [k, v] of Object.entries(ENEMY_DATA)) enemyImgs[k] = mk(v);
  const propImgs: Record<string, HTMLImageElement> = {};
  for (const [k, v] of Object.entries(PROP_DATA)) propImgs[k] = mk(v);
  const tileImgs = { floor: mk(TILE_DATA.floor, true), wall: mk(TILE_DATA.wall, true) };
  bank = {
    ready: false, enemies: enemyImgs, props: propImgs, tiles: tileImgs,
    onTilesReady: (cb: () => void) => { if (tilesLoadedCount >= 2) cb(); else tileCallbacks.push(cb); },
  };
  return bank;
}
